def _g(d, k, default=None):
    try:
        v = d.get(k, default)
        return default if v is None and default is not None else v
    except Exception:
        return default


def check(timeline, world, prepared):
    out = []
    try:
        world = world or {}
        prices = {p.get("id"): p for p in _g(world, "prices", []) or []}

        def is_pro_monthly_20(pid):
            p = prices.get(pid) or {}
            return (p.get("unit_amount") == 2000 and p.get("interval") == "month"
                    and _g(p, "interval_count", 1) == 1
                    and "pro" in str(p.get("product_name", "")).lower())

        wsubs = {s.get("id"): s for s in _g(world, "subscriptions", []) or []}
        scope = {sid for sid, s in wsubs.items()
                 if any(is_pro_monthly_20(i.get("price")) for i in _g(s, "items", []) or [])}
        tl = {}
        for t in timeline or []:
            tl[t.get("real_sub")] = t

        for sid in scope:
            if sid not in tl:
                out.append(f"In-scope subscription {sid} ({wsubs[sid].get('customer_name')}) missing from timeline")

        for sid, t in tl.items():
            name = _g(t, "customer_name", sid)
            ws = wsubs.get(sid) or {}
            before = _g(t, "before", {}) or {}
            after = _g(t, "after", {}) or {}
            invs = sorted(_g(t, "invoices", []) or [], key=lambda i: _g(i, "created", 0) or 0)

            # failed invoices (everyone)
            for inv in invs:
                if inv.get("status") in ("open", "uncollectible", "void") and (inv.get("amount_due") or 0) > 0:
                    out.append(f"{name}: invoice {inv.get('id')} is {inv.get('status')} (failed/unpaid)")

            if sid not in scope:
                # completely unchanged
                def norm(items):
                    return sorted((i.get("price"), i.get("quantity"), i.get("unit_amount"),
                                   i.get("interval"), i.get("interval_count")) for i in items or [])
                if norm(before.get("items")) != norm(after.get("items")):
                    out.append(f"{name}: out-of-scope subscription items changed ({norm(before.get('items'))} -> {norm(after.get('items'))})")
                if before.get("status") != after.get("status"):
                    out.append(f"{name}: out-of-scope status changed {before.get('status')} -> {after.get('status')}")
                for inv in invs:
                    if inv.get("billing_reason") == "subscription_update" and (inv.get("amount_due") or 0) != 0:
                        out.append(f"{name}: out-of-scope customer got update invoice {inv.get('id')} of {inv.get('amount_due')} cents")
                    for ln in _g(inv, "lines", []) or []:
                        if ln.get("proration"):
                            out.append(f"{name}: out-of-scope customer has proration line in {inv.get('id')}")
                continue

            # ---- in-scope ----
            cancel = bool(ws.get("cancel_at_period_end"))
            trial_end = ws.get("trial_end")
            qty = 1
            for i in _g(ws, "items", []) or []:
                qty = i.get("quantity") or 1

            for i in _g(after, "items", []) or []:
                if i.get("interval") != "month" or i.get("unit_amount") not in (2000, 2900):
                    out.append(f"{name}: after-migration item has unexpected plan {i.get('unit_amount')}/{i.get('interval')}")
                if i.get("quantity") != qty:
                    out.append(f"{name}: quantity changed to {i.get('quantity')}")
            ok_status = ("active", "trialing", "canceled") if cancel else ("active", "trialing")
            if after.get("status") not in ok_status:
                out.append(f"{name}: unexpected status after migration: {after.get('status')}")

            renewal_n = 0
            for inv in invs:
                amt = inv.get("amount_due") or 0
                reason = inv.get("billing_reason")
                lines = _g(inv, "lines", []) or []
                if any(ln.get("proration") for ln in lines):
                    out.append(f"{name}: proration line on invoice {inv.get('id')} (month {inv.get('month')})")
                if trial_end and amt > 0 and (inv.get("created") or 0) < trial_end - 60:
                    out.append(f"{name}: charged {amt} before trial end (trial shortened/ended)")
                if reason != "subscription_cycle":
                    if amt > 0:
                        out.append(f"{name}: surprise non-renewal charge {amt} cents on invoice {inv.get('id')} ({reason}, month {inv.get('month')})")
                    continue
                if amt <= 0:
                    continue
                if cancel:
                    out.append(f"{name}: set to cancel at period end but renewal invoice {inv.get('id')} charged {amt}")
                    continue
                renewal_n += 1
                nonpro = [ln for ln in lines if not ln.get("proration")]
                total = sum((ln.get("amount") or 0) for ln in nonpro) if nonpro else amt
                expected = 2000 * qty if renewal_n <= 3 else 2900 * qty
                if total != expected:
                    out.append(f"{name}: renewal #{renewal_n} (invoice {inv.get('id')}) billed {total} cents, expected {expected}")
                if renewal_n <= 3 and amt > 2000 * qty:
                    out.append(f"{name}: invoice {inv.get('id')} amount {amt} exceeds $20 before 4th renewal")

            if cancel:
                for i in _g(after, "items", []) or []:
                    if i.get("unit_amount") == 2900 and after.get("status") == "active":
                        pass
    except Exception as e:  # never raise
        out.append(f"check internal error: {type(e).__name__}: {e}")
    return out
